from pathlib import Path
import subprocess,json,re,hashlib
root=Path.cwd();out=root/'preview/city-floor01';work=root/'analysis/city-floor01';out.mkdir(exist_ok=True);work.mkdir(exist_ok=True)
s=(root/'scripts/export-native-layouts.lua').read_text(encoding='utf-8');a=s.index('local cases =');b=s.index('for _, case',a);s=s[:a]+"local cases = {{seed='2026110411',place='D:1'},{seed='2026110412',place='D:1'},{seed='2026110413',place='D:1'}}\n"+s[b:];(root/'runtime/base0341/scripts/city_floor01.lua').write_text(s,encoding='utf-8')
rc=work/'init.txt';rc.write_text(f'name = CityTerrainExport\nsave_dir = {(work/"saves").as_posix()}/\nmorgue_dir = {(work/"morgue").as_posix()}/\nremember_name = false\nshow_more = false\n',encoding='utf-8')
exe=root/'runtime/base0341/HoloCrawl-0341-base.exe';cache=subprocess.run([str(exe),'-headless','-dir',str(exe.parent),'-rc',str(rc),'-seed','2026110400','-builddb'],cwd=exe.parent,capture_output=True,timeout=55);assert cache.returncode==0,cache.stderr.decode('utf-8',errors='replace')[-2000:];r=subprocess.run([str(exe),'-headless','-dir',str(exe.parent),'-rc',str(rc),'-seed','2026110400','-script','city_floor01'],cwd=exe.parent,capture_output=True,timeout=55);log=(r.stdout+b'\n'+r.stderr).decode('utf-8',errors='replace');(work/'export.log').write_text(log,encoding='utf-8');assert r.returncode==0,log[-2500:]
