payload={'engine':'DCSS0.34.1','method':'native headless upstream D:1 builder; terrain only, no game window/play session','maps':maps,'nativeBinarySha256':hashlib.sha256(exe.read_bytes()).hexdigest()};(out/'native-d1.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2),encoding='utf-8');(out/'native-d1.js').write_text('globalThis.NativeD1='+json.dumps(payload,ensure_ascii=False)+';',encoding='utf-8');print(json.dumps([{'seed':m['seed'],'vaults':m['vaults'],'palette':m['palette']}for m in maps],ensure_ascii=False))
